<?php
require_once __DIR__.'/../config/config.php'; require_once __DIR__.'/../includes/session.php'; require_once __DIR__.'/../includes/auth.php';
require_login(); require_module_access($conn,'hr_staff','view');
$canCreate=can_module_action($conn,'hr_staff','create'); $canEdit=can_module_action($conn,'hr_staff','edit'); $csrf=csrf_token();
$types=['Permanent','Fixed Term','Locum','Casual','Internship','Consultancy','Other']; $statuses=['Draft','Active','Renewed','Expired','Terminated']; $error=''; $message='';
$validDate=static function(string $v):bool { if($v==='')return true; $d=DateTime::createFromFormat('!Y-m-d',$v); return $d instanceof DateTime && $d->format('Y-m-d')===$v; };
if($_SERVER['REQUEST_METHOD']==='POST'){
 $id=(int)($_POST['id']??0);
 if(!verify_csrf_token($_POST['csrf_token']??null)) $error='Your security token expired. Refresh and try again.';
 elseif(($id>0&&!$canEdit)||($id===0&&!$canCreate)){http_response_code(403);exit('Forbidden: HR contract permission required.');}
 else{
  $staffId=(int)($_POST['staff_id']??0); $ref=trim((string)($_POST['contract_reference']??'')); $type=(string)($_POST['contract_type']??'Fixed Term'); $start=trim((string)($_POST['start_date']??'')); $end=trim((string)($_POST['end_date']??'')); $status=(string)($_POST['status']??'Active'); $notes=trim((string)($_POST['renewal_notes']??''));
  if($staffId<1||!in_array($type,$types,true)||!in_array($status,$statuses,true)||$start===''||!$validDate($start)||!$validDate($end)||($end!==''&&$end<$start)) $error='Choose a staff member and valid contract type, status and dates. End date cannot precede start date.';
  elseif(strlen($ref)>80||strlen($notes)>1000) $error='Contract reference or notes exceed the allowed length.';
  else{
   $check=$conn->prepare('SELECT id FROM hr_staff WHERE id=? LIMIT 1');
   if(!$check)$error='Unable to validate the staff record.';
   else{$check->bind_param('i',$staffId);$check->execute();$exists=$check->get_result()->fetch_assoc();$check->close();
    if(!$exists)$error='The selected staff record does not exist.';
    else{
     $refValue=$ref!==''?$ref:null; $endValue=$end!==''?$end:null; $notesValue=$notes!==''?$notes:null; $actor=(int)($_SESSION['user_id']??0);
     try{
      if($id>0){$stmt=$conn->prepare('UPDATE hr_staff_contracts SET staff_id=?,contract_reference=?,contract_type=?,start_date=?,end_date=?,status=?,renewal_notes=?,updated_by=? WHERE id=?');if(!$stmt)throw new RuntimeException('prepare update failed');$stmt->bind_param('issssssii',$staffId,$refValue,$type,$start,$endValue,$status,$notesValue,$actor,$id);$stmt->execute();$stmt->close();$message='Contract record updated.';if(function_exists('audit'))audit('hr_contract_updated','contract_id='.$id.',staff_id='.$staffId.',status='.$status);}
      else{$stmt=$conn->prepare('INSERT INTO hr_staff_contracts (staff_id,contract_reference,contract_type,start_date,end_date,status,renewal_notes,created_by,updated_by) VALUES (?,?,?,?,?,?,?,?,?)');if(!$stmt)throw new RuntimeException('prepare insert failed');$stmt->bind_param('issssssii',$staffId,$refValue,$type,$start,$endValue,$status,$notesValue,$actor,$actor);$stmt->execute();$newId=(int)$conn->insert_id;$stmt->close();$message='Contract record created.';if(function_exists('audit'))audit('hr_contract_created','contract_id='.$newId.',staff_id='.$staffId.',status='.$status);}
     }catch(Throwable $ex){error_log('HR contract save failed: '.$ex->getMessage());$error='Contract could not be saved. Check if the contract reference is already in use.';}
    }
   }
  }
 }
}
$edit=null;$editId=(int)($_GET['edit']??0);if($editId>0&&$canEdit){$st=$conn->prepare('SELECT * FROM hr_staff_contracts WHERE id=? LIMIT 1');if($st){$st->bind_param('i',$editId);$st->execute();$edit=$st->get_result()->fetch_assoc();$st->close();}}
$staff=$conn->query("SELECT id,staff_no,first_name,last_name,department FROM hr_staff WHERE status <> 'Separated' ORDER BY department,last_name");
$rows=$conn->query("SELECT c.*,s.staff_no,s.first_name,s.last_name,s.department,CASE WHEN c.status IN ('Terminated','Draft') THEN c.status WHEN c.end_date<CURDATE() THEN 'Expired' WHEN c.end_date<=DATE_ADD(CURDATE(),INTERVAL 60 DAY) THEN 'Renewal due' ELSE c.status END contract_state FROM hr_staff_contracts c JOIN hr_staff s ON s.id=c.staff_id ORDER BY CASE WHEN c.status IN ('Terminated','Draft') THEN 4 WHEN c.end_date<CURDATE() THEN 0 WHEN c.end_date<=DATE_ADD(CURDATE(),INTERVAL 60 DAY) THEN 1 ELSE 2 END,c.end_date,s.last_name");
$summary=$conn->query("SELECT COUNT(*) total,SUM(status='Active' AND end_date<CURDATE()) expired,SUM(status='Active' AND end_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 60 DAY)) due FROM hr_staff_contracts");$counts=$summary?$summary->fetch_assoc():['total'=>0,'expired'=>0,'due'=>0];
$e=static fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8'); include __DIR__.'/../includes/header.php'; include __DIR__.'/../includes/sidebar.php';
?>
<style>
