 th{background:#f7f9fc;color:#68778b;text-transform:uppercase;font-size:.65rem;letter-spacing:.05em}.hct-name{font-weight:800;color:#172b45}.hct-sub{display:block;color:#77869a;font-size:.74rem;margin-top:3px}.hct-pill{display:inline-block;padding:5px 8px;border-radius:99px;background:#edf2f7;color:#475569;font-size:.66rem;font-weight:800}.hct-current{background:#e9fbf1;color:#087443}.hct-expired{background:#fff0f0;color:#a22}.hct-soon{background:#fff7e6;color:#996300}@media(max-width:800px){.hct-form{grid-template-columns:repeat(2,minmax(0,1fr))}@media(max-width:560px){.hct{padding:16px 11px}.hct-form,.hct-metrics{grid-template-columns:1fr}.hct-hero{padding:20px}}
</style>
<div class="hct"><div class="hct-wrap"><section class="hct-hero"><div><div style="font-size:.68rem;letter-spacing:.14em;text-transform:uppercase;font-weight:800;margin-bottom:6px">People operations · Employment lifecycle</div><h2>Contract Register</h2><p>Track contract dates, renewal deadlines and agreement status.</p></div><a class="hct-btn" style="background:#fff;color:#0b4e8b" href="/hospital_system/hr/index.php"><i class="fas fa-arrow-left"></i> Staff Directory</a></section>
<?php if($error!==''):?><div class="hct-alert hct-error"><?= $e($error) ?></div><?php endif;?><?php if($message!==''):?><div class="hct-alert hct-success"><?= $e($message) ?></div><?php endif;?>
<section class="hct-metrics"><div class="hct-metric"><small>Contract records</small><strong><?= (int)($counts['total']??0) ?></strong></div><div class="hct-metric"><small>Expired active contracts</small><strong><?= (int)($counts['expired']??0) ?></strong></div><div class="hct-metric"><small>Active contracts ending in 60 days</small><strong><?= (int)($counts['due']??0) ?></strong></div></section>
<?php if(($canCreate&&!$edit)||($edit&&$canEdit)):?><section class="hct-card"><div class="hct-head"><?= $edit?'Edit contract':'Add contract' ?></div><form method="post" class="hct-form"><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>">
<div class="hct-field"><label>Staff member *</label><select name="staff_id" required><option value="">Select employee</option><?php if($staff):while($s=$staff->fetch_assoc()):?><option value="<?= (int)$s['id'] ?>" <?= ((int)($edit['staff_id']??0)===(int)$s['id'])?'selected':'' ?>><?= $e(($s['staff_no']?:'STAFF').' · '.$s['first_name'].' '.$s['last_name'].' — '.$s['department']) ?></option><?php endwhile;$staff->data_seek(0);endif;?></select></div>
<div class="hct-field"><label>Contract reference</label><input name="contract_reference" maxlength="80" value="<?= $e($edit['contract_reference']??'') ?>" placeholder="Optional internal reference"></div><div class="hct-field"><label>Contract type</label><select name="contract_type"><?php foreach($types as $t):?><option value="<?= $e($t) ?>" <?= (($edit['contract_type']??'Fixed Term')===$t)?'selected':'' ?>><?= $e($t) ?></option><?php endforeach;?></select></div>
<div class="hct-field"><label>Start date *</label><input type="date" name="start_date" required value="<?= $e($edit['start_date']??'') ?>"></div><div class="hct-field"><label>End date</label><input type="date" name="end_date" value="<?= $e($edit['end_date']??'') ?>"></div><div class="hct-field"><label>Record status</label><select name="status"><?php foreach($statuses as $st):?><option value="<?= $e($st) ?>" <?= (($edit['status']??'Active')===$st)?'selected':'' ?>><?= $e($st) ?></option><?php endforeach;?></select></div>
<div class="hct-field hct-wide"><label>Renewal / HR notes</label><textarea name="renewal_notes" maxlength="1000"><?= $e($edit['renewal_notes']??'') ?></textarea></div><div class="hct-wide"><button class="hct-btn hct-primary" type="submit"><i class="fas fa-save"></i> Save contract</button><?php if($edit):?> <a class="hct-btn hct-muted" href="contracts.php">Cancel</a><?php endif;?></div></form></section><?php endif;?>
<section class="hct-card"><div class="hct-head">Contracts · expiry and renewal exceptions first</div><div class="hct-tablewrap"><table class="hct-table"><thead><tr><th>Staff member</th><th>Reference / type</th><th>Dates</th><th>Status</th><th>Renewal notes</th><th>Action</th></tr></thead><tbody><?php if($rows&&$rows->num_rows):while($r=$rows->fetch_assoc()):$state=(string)$r['contract_state'];$cls=$state==='Expired'?'hct-expired':($state==='Renewal due'?'hct-soon':(in_array($state,['Active','Renewed'],true)?'hct-current':''));?><tr><td><span class="hct-name"><?= $e($r['first_name'].' '.$r['last_name']) ?></span><span class="hct-sub"><?= $e($r['staff_no'].' · '.$r['department']) ?></span></td><td><?= $e($r['contract_reference']?:'No reference') ?><span class="hct-sub"><?= $e($r['contract_type']) ?></span></td><td><?= $e($r['start_date']) ?><span class="hct-sub">Ends: <?= $e($r['end_date']?:'No end date') ?></span></td><td><span class="hct-pill <?= $cls ?>"><?= $e($state) ?></span></td><td><?= $e($r['renewal_notes']?:'—') ?></td><td><?php if($canEdit):?><a class="hct-btn hct-muted" href="?edit=<?= (int)$r['id'] ?>"><i class="fas fa-pen"></i> Edit</a><?php else:?>—<?php endif;?></td></tr><?php endwhile;else:?><tr><td colspan="6" style="text-align:center;padding:32px;color:#77869a">No contract records yet. Add current agreements to monitor renewal dates.</td></tr><?php endif;?></tbody></table></div></section></div></div>
